import sys, itertools; sys.path[:0]=['/workspace/project','/opt/emicro-deps']
import syntax
from compiler import automata, compiler
def depth_policy(n):                      # not() chain of predicate depth n
    return 'not('*(n-1) + 'match(A)' + ')'*(n-1) + ' allow;'
for n in (15,16,17,18,100000):
    text=depth_policy(n) if n<1000 else 'not('*99999+'match(A) allow;'
    try:
        rules,a,s=syntax.parse(text)
        try:
            img=automata.compile_rules(rules,[1,2],{'A':0,'B':1})
            print('depth',n,'rows',img['rows_count'],'accept',img['accept'])
        except Exception as e: print('depth',n,'compile',type(e).__name__,e)
    except Exception as e:
        print('depth',n,'parse',type(e).__name__,e)
# right-nested binary chain depth 16 and 17
def right_chain(n):
    text='match(A)'
    for _ in range(n-1): text='(match(B) or %s)'%text
    return text+' allow;'
for n in (16,17):
    try:
        rules,_,_=syntax.parse(right_chain(n))
        print('chain',n,'parsed', automata.compile_rules(rules,[1,2],{'A':0,'B':1})['rows_count'])
    except Exception as e: print('chain',n,'error',type(e).__name__,e)
EOF
